func TestEnumEnvelopeStatus(t *testing.T) {
	t.Run("NewFromString_OK", func(t *testing.T) {
		t.Parallel()
		val, err := NewEnvelopeStatusFromString("OK")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, EnvelopeStatus("OK"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_ERROR", func(t *testing.T) {
		t.Parallel()
		val, err := NewEnvelopeStatusFromString("ERROR")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, EnvelopeStatus("ERROR"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewEnvelopeStatusFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewEnvelopeStatusFromString("OK")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

